// ============================================================
// АРМЕЙСКИЙ ФОРЖ — пехота и наземная техника СВОИМ движком
// ------------------------------------------------------------
// ⚠️ ПОЧЕМУ ОТДЕЛЬНЫЙ ФАЙЛ. До августа 2026 армия ехала на корабельном
// движке один в один: тот же hull_gen (обшивка, бронепояс, надстройка,
// дюзы), та же палуба-решётка, та же сцена 960×470 с вписыванием ЛЮБОГО
// юнита в кадр. Следствия были три, и все три — не косметика:
//   1) МАСШТАБА НЕ БЫЛО ВООБЩЕ. sc = min(944/длина, 408/ширину) — то есть
//      пехотинец рисовался ровно такого же размера, как дредноут. Танк,
//      БТР и боец выглядели одинаково крупными, размер класса на глаз не
//      читался никак.
//   2) ВИД СВЕРХУ. Танк сверху — прямоугольник. Ни башни, ни ствола, ни
//      гусеницы, ни клиренса: всё, чем техника узнаётся, — в профиле.
//   3) ПЕХОТА НЕ МОГЛА ВЗЯТЬ ОРУЖИЕ. Оружие вешается на узел палубы, а
//      самый лёгкий узел (CN_SYS.gun_s) стоит 30 E. У бойца реактор —
//      «Его отважное сердце» на 0 E (следующий — 12 E), поэтому любой
//      узел уводил энергосеть в минус, срабатывал жёсткий откат и
//      вылезало «Энергосеть перегружена — реактор не тянет». Это и есть
//      баг «пехотные реакторы сломаны»: реакторы целы, к бойцу приложили
//      КОРАБЕЛЬНУЮ ПАЛУБУ. Здесь пехота вешает оружие ПРЯМО в mounts,
//      без узла и без 30 E (сервер читает mounts, см. cnVehCollectData).
//
// Что делает файл: рисует сцену армейского юнита в АБСОЛЮТНОМ масштабе
// (метры → пиксели по одной шкале для всех классов), с метровой линейкой
// и силуэтом бойца 1.8 м для сравнения, и даёт пехоте свой экран
// «снаряжение отделения» вместо палубы.
//
// Контракт данных НЕ меняется: класс/броня/реактор/двигатель/щит — те же
// скрытые select'ы конструктора, оружие — те же CN.shipLayout.mounts.
// Публикация (cnVehCollectData → economy_publish_unit) не знает об этом
// файле ничего.
// ============================================================

// ── РЕАЛЬНЫЕ РАЗМЕРЫ, МЕТРЫ ─────────────────────────────────
// Источник правды по «крупности» — gabarit класса в KV (пехота 1, БТР 5,
// арта 4, танк 9). Но gabarit — одно число, а профиль требует длины И
// высоты, поэтому здесь габарит разложен в пару с сохранением порядка:
// боец < БТР < танк < САУ. Менять числа можно, ПОРЯДОК ломать нельзя —
// на нём держится вся читаемость сцены.
const AF_DIM = {
  peh:   { len: 0.62, hgt: 1.90, kind: 'foot',  label: 'боец' },
  btr:   { len: 7.40, hgt: 2.35, kind: 'wheel', axles: 3, label: 'БТР' },
  tanki: { len: 9.20, hgt: 2.30, kind: 'track', label: 'танк' },
  arta:  { len: 8.60, hgt: 2.55, kind: 'spg',   label: 'САУ' },
};
// Единая линейка сцены: 1 метр = столько пикселей. ОДНО число на все
// классы — в этом весь смысл, разные масштабы вернули бы прежнюю ложь.
// ⚠️ 52, а не 62: в кадр должен влезать не корпус, а СИЛУЭТ ЦЕЛИКОМ — рельсотрон
// вылетает за нос на 6 м, и на 62 px/м ствол уезжал за край полотна.
const AF_PXM = 52;
// У пехоты своя сцена (боец — предмет кадра, а не машина в общем строю),
// поэтому крупнее; масштаб честно подписан на линейке.
const AF_PXM_FOOT = 185;
const AF_MAN_H = 1.80;                 // рост эталонного силуэта, м

function afIs(k) { return !!AF_DIM[k]; }
function afFoot(k) { return k === 'peh'; }
// Юнит рисуем своим движком только в армейском форже: корабельные классы
// и авиация (у неё вид сверху осмыслен — крыло) остаются на hull_gen.
function afActive() {
  return !!(typeof CN !== 'undefined' && CN.cat === 'army' && CN.def && CN.def.db
    && afIs((typeof cnId === 'function' && cnId('cn-class') || {}).value));
}

// ── МЕЛОЧЁВКА ───────────────────────────────────────────────
const afN = n => (Math.round(n * 100) / 100).toFixed(2);
function afPoly(pts, attrs) { return `<path d="M${pts.map(p => afN(p[0]) + ',' + afN(p[1])).join(' L')} Z" ${attrs}/>`; }
function afLine(x1, y1, x2, y2, attrs) { return `<line x1="${afN(x1)}" y1="${afN(y1)}" x2="${afN(x2)}" y2="${afN(y2)}" ${attrs}/>`; }
function afRect(x, y, w, h, attrs) { return `<rect x="${afN(x)}" y="${afN(y)}" width="${afN(Math.max(0, w))}" height="${afN(Math.max(0, h))}" ${attrs}/>`; }

// Тон металла — от РЕЦЕПТА брони, как на верфи: игрок должен видеть, что
// сменил именно бронирование, а не «покрасил в другой цвет наугад».
function afTone(armorObj) {
  const cat = (armorObj && armorObj.category) || '';
  if (/light/i.test(cat)) return { base: '#6e7a86', lit: '#8f9daa', dark: '#3d454e' };
  if (/heavy|composite/i.test(cat)) return { base: '#5b6570', lit: '#7d8894', dark: '#333a42' };
  if (/exotic|energy/i.test(cat)) return { base: '#5f6b7d', lit: '#8896ab', dark: '#343c48' };
  return { base: '#646f7b', lit: '#8794a1', dark: '#373f47' };
}

// ════════════════════════════════════════════════════════════
// ТЕХНИКА: ПРОФИЛЬ (вид сбоку), метры → пиксели
// Все геометрии строятся в МЕТРАХ и переводятся функциями X/Y, поэтому
// толщины линий остаются пиксельными и не разъезжаются при смене класса.
// ── ЯЗЫК ОБЪЁМА (тот же, что у корабельной верфи, hull_gen.js) ─────────────
// ⚠️ ПОЧЕМУ НЕ ПЛОСКИЕ ЗАЛИВКИ. Первая версия армейского рендера красила каждую
// деталь одним цветом и обводила волоском — получалась аппликация из бумаги.
// Корабли выглядят вещами по трём приёмам, и здесь ровно они же:
//   1) ГРАДИЕНТ ПОПЕРЁК ПЛИТЫ — верхняя кромка ловит свет, нижняя уходит в тень;
//   2) AO — размытая чёрная обводка под деталью сажает её на соседнюю;
//   3) КАНТ — чернильный контур + светлый волосок по свету собирают силуэт.
// И четвёртое, главное: ПЛОТНОСТЬ ДЕТАЛЕЙ СЧИТАЕТСЯ В МЕТРАХ. Болты через 0.3 м,
// траки через 0.26 м — у длинной машины их БОЛЬШЕ, а не крупнее. Именно
// количество деталей и передаёт размер.
const AF_INK = '#0b0d10', AF_GROOVE = '#0e1216';
function afHex(h) { h = String(h).replace('#', ''); if (h.length === 3) h = h.split('').map(c => c + c).join(''); return [0, 2, 4].map(i => parseInt(h.substr(i, 2), 16)); }
function afRgb(a) { return '#' + a.map(v => Math.max(0, Math.min(255, Math.round(v))).toString(16).padStart(2, '0')).join(''); }
function afSh(c, k) { const A = afHex(c); return afRgb(A.map(v => k > 0 ? v + (255 - v) * k : v * (1 + k))); }
let AF_DEFS = [], AF_UID = 0;
// Градиент поперёк плиты в ЭКРАННЫХ координатах (ya — верх, yb — низ).
function afGrad(base, ya, yb, lift) {
  const id = 'afg' + (++AF_UID), l = lift || 0;
  AF_DEFS.push(`<linearGradient id="${id}" gradientUnits="userSpaceOnUse" x1="0" y1="${afN(ya)}" x2="0" y2="${afN(yb)}">`
    + `<stop offset="0" stop-color="${afSh(base, 0.30 + l)}"/>`
    + `<stop offset="0.34" stop-color="${afSh(base, 0.06 + l * 0.5)}"/>`
    + `<stop offset="0.74" stop-color="${afSh(base, -0.14)}"/>`
    + `<stop offset="1" stop-color="${afSh(base, -0.38)}"/></linearGradient>`);
  return `url(#${id})`;
}
// Плита: AO под кромкой → заливка → чернильный кант → волосок света.
function afSolid(d, fill, ao, tint) {
  const a = Math.max(1.1, Math.min(4, ao == null ? 2 : ao));
  return `<path d="${d}" fill="none" stroke="#000" stroke-width="${afN(a)}" opacity="0.5" style="filter:blur(1.2px)"/>`
    + `<path d="${d}" fill="${fill}" stroke="${AF_INK}" stroke-width="0.7" stroke-linejoin="round"/>`
    + (tint ? `<path d="${d}" fill="none" stroke="${afSh(tint, 0.6)}" stroke-width="0.5" opacity="0.20"/>` : '');
}

// ════════════════════════════════════════════════════════════
// ТЕХНИКА: ПРОФИЛЬ (вид сбоку), метры → пиксели
// Геометрия строится в МЕТРАХ и переводится функциями X/Y — толщины линий
// остаются пиксельными и не разъезжаются при смене класса.
// ════════════════════════════════════════════════════════════
function afVehicleSvg(k, C, X, Y) {
  const D = AF_DIM[k], L = D.len, P = [];
  const T = afTone(C.armorObj), tint = T.base, aRt = C.aRt;
  const px = m => m * AF_PXM;
  const p = (x, y) => `${afN(X(x))},${afN(Y(y))}`;
  const M = (x, y) => `M${p(x, y)}`, Ln = (x, y) => `L${p(x, y)}`;
  const poly = pts => 'M' + pts.map(q => p(q[0], q[1])).join('L') + 'Z';
  const plate = (pts, lift, ao) => {                       // плита с градиентом по своей высоте
    const ys = pts.map(q => q[1]);
    return afSolid(poly(pts), afGrad(tint, Y(Math.max(...ys)), Y(Math.min(...ys)), lift), ao, tint);
  };
  const seam = (x1, y1, x2, y2, op) => `<path d="${M(x1, y1) + Ln(x2, y2)}" fill="none" stroke="${AF_INK}" stroke-width="0.9" opacity="${op || 0.55}"/>`;
  const bolt = (x, y, r) => `<circle cx="${afN(X(x))}" cy="${afN(Y(y))}" r="${afN(px(r || 0.028))}" fill="${afSh(tint, -0.3)}" stroke="${afSh(tint, 0.45)}" stroke-width="0.4" opacity="0.9"/>`;
  const box = (x, y, w, h, lift) => plate([[x, y], [x + w, y], [x + w, y + h], [x, y + h]], lift == null ? 0.05 : lift, 1.6);

  const dead = !C.engObj || /нет двиг/i.test(C.engObj.name || '');
  const track = D.kind === 'track' || D.kind === 'spg';
  const top = D.hgt;
  let floor;

  // Контактная тень на грунте — «отрывает» машину от фона.
  P.push(`<ellipse cx="${afN(X(L / 2))}" cy="${afN(Y(0))}" rx="${afN(px(L / 2 + 0.3))}" ry="${afN(px(0.16))}" fill="#000" opacity="0.45" style="filter:blur(4px)"/>`);

  // ── ХОДОВАЯ ───────────────────────────────────────────────
  if (track) {
    const clr = 0.40, wr = 0.33, tt = clr + wr * 2;
    floor = tt - 0.10;
    const x0 = 0.12, x1 = L - 0.12;
    // Тёмное нутро ходовой (паз), поверх него — катки, поверх — лента с траками.
    P.push(afSolid(poly([[x0, 0.02], [x1, 0.02], [x1, tt], [x0, tt]]), AF_GROOVE, 2.2));
    const nW = D.kind === 'spg' ? 7 : 6;
    for (let i = 0; i < nW; i++) {
      const cx = x0 + 0.62 + (x1 - x0 - 1.24) * (i / (nW - 1)), cy = clr + wr * 0.55;
      P.push(`<circle cx="${afN(X(cx))}" cy="${afN(Y(cy))}" r="${afN(px(wr * 0.78))}" fill="${afGrad(tint, Y(cy + wr * 0.78), Y(cy - wr * 0.78))}" stroke="${AF_INK}" stroke-width="0.8"/>`);
      P.push(`<circle cx="${afN(X(cx))}" cy="${afN(Y(cy))}" r="${afN(px(wr * 0.3))}" fill="${afSh(tint, -0.34)}" stroke="${AF_INK}" stroke-width="0.6"/>`);
      P.push(bolt(cx, cy, 0.035));
      // Балансир подвески — рычаг от катка к борту.
      P.push(`<path d="${M(cx, cy) + Ln(cx - 0.28, cy + 0.34)}" fill="none" stroke="${afSh(tint, -0.28)}" stroke-width="${afN(px(0.06))}" stroke-linecap="round" opacity="0.9"/>`);
    }
    // Ведущее колесо с зубьями (корма) и ленивец (нос).
    [[x0 + 0.46, 1], [x1 - 0.46, 0]].forEach(([cx, teeth]) => {
      const cy = clr + wr * 0.95, r = wr * 1.02;
      P.push(`<circle cx="${afN(X(cx))}" cy="${afN(Y(cy))}" r="${afN(px(r))}" fill="${afGrad(tint, Y(cy + r), Y(cy - r), 0.1)}" stroke="${AF_INK}" stroke-width="0.9"/>`);
      if (teeth) for (let a = 0; a < 10; a++) {
        const an = a / 10 * Math.PI * 2;
        P.push(`<path d="${M(cx + Math.cos(an) * r * 0.82, cy + Math.sin(an) * r * 0.82) + Ln(cx + Math.cos(an) * r, cy + Math.sin(an) * r)}" fill="none" stroke="${AF_INK}" stroke-width="1.1" opacity="0.75"/>`);
      }
      P.push(bolt(cx, cy, 0.045));
    });
    // Поддерживающие ролики по верхней ветви.
    for (let i = 0; i < 3; i++) {
      const cx = x0 + 1.2 + (x1 - x0 - 2.4) * (i / 2);
      P.push(`<circle cx="${afN(X(cx))}" cy="${afN(Y(tt - 0.06))}" r="${afN(px(0.09))}" fill="${afSh(tint, -0.12)}" stroke="${AF_INK}" stroke-width="0.7"/>`);
    }
    // ЛЕНТА: отдельные траки, шаг 0.26 м — у длинной машины их больше, а не крупнее.
    const step = 0.26;
    for (let t = x0 + 0.1; t < x1 - 0.1; t += step) {
      const w = step * 0.82;
      P.push(afSolid(poly([[t, 0.0], [t + w, 0.0], [t + w * 0.86, 0.17], [t + w * 0.14, 0.17]]), afSh(tint, -0.30 + (Math.round(t * 7) % 2) * 0.06), 1.2));
      P.push(afSolid(poly([[t, tt - 0.14], [t + w, tt - 0.14], [t + w * 0.86, tt], [t + w * 0.14, tt]]), afSh(tint, -0.2 + (Math.round(t * 7) % 2) * 0.05), 1.1));
    }
    // Носовой и кормовой обвод ленты — дуги вокруг спрокета/ленивца.
    [[x0 + 0.46, -1], [x1 - 0.46, 1]].forEach(([cx, s]) => {
      const r0 = wr * 1.02, r1 = r0 + 0.15, cy = clr + wr * 0.95;
      P.push(`<path d="${M(cx, cy - r1) } A ${afN(px(r1))} ${afN(px(r1))} 0 0 ${s > 0 ? 0 : 1} ${p(cx, cy + r1)} L${p(cx, cy + r0)} A ${afN(px(r0))} ${afN(px(r0))} 0 0 ${s > 0 ? 1 : 0} ${p(cx, cy - r0)}Z" fill="${afSh(tint, -0.26)}" stroke="${AF_INK}" stroke-width="0.7"/>`);
    });
    if (dead) P.push(`<path d="${M(L * 0.34, 0.02) + Ln(L * 0.34, floor)}" fill="none" stroke="var(--err)" stroke-width="2" stroke-dasharray="4 3"/>`);
  } else {
    const wr = 0.55;
    floor = 0.90;
    const n = D.axles || 3;
    for (let i = 0; i < n; i++) {
      const cx = 1.25 + (L - 2.9) * (i / (n - 1));
      // Амортизатор и рычаг подвески — колесо не приклеено к борту.
      P.push(`<path d="${M(cx, wr + 0.1) + Ln(cx + 0.1, floor + 0.18)}" fill="none" stroke="${afSh(tint, -0.3)}" stroke-width="${afN(px(0.07))}" stroke-linecap="round"/>`);
      P.push(`<circle cx="${afN(X(cx))}" cy="${afN(Y(wr))}" r="${afN(px(wr))}" fill="${afGrad('#23272c', Y(wr + wr), Y(wr - wr), 0.06)}" stroke="${AF_INK}" stroke-width="1"/>`);
      // Протектор: грунтозацепы по ободу, шаг постоянный в метрах.
      for (let a = 0; a < 18; a++) {
        const an = a / 18 * Math.PI * 2;
        P.push(`<path d="${M(cx + Math.cos(an) * wr * 0.88, wr + Math.sin(an) * wr * 0.88) + Ln(cx + Math.cos(an) * wr, wr + Math.sin(an) * wr)}" fill="none" stroke="#0d1013" stroke-width="1.6" opacity="0.85"/>`);
      }
      P.push(`<circle cx="${afN(X(cx))}" cy="${afN(Y(wr))}" r="${afN(px(wr * 0.46))}" fill="${afGrad(tint, Y(wr + wr * 0.46), Y(wr - wr * 0.46), 0.1)}" stroke="${AF_INK}" stroke-width="0.8"/>`);
      for (let a = 0; a < 6; a++) { const an = a / 6 * Math.PI * 2; P.push(bolt(cx + Math.cos(an) * wr * 0.3, wr + Math.sin(an) * wr * 0.3, 0.026)); }
      P.push(`<circle cx="${afN(X(cx))}" cy="${afN(Y(wr))}" r="${afN(px(wr * 0.14))}" fill="${afSh(tint, 0.35)}" stroke="${AF_INK}" stroke-width="0.6"/>`);
      if (dead) P.push(`<path d="${M(cx - wr * 0.7, wr - wr * 0.7) + Ln(cx + wr * 0.7, wr + wr * 0.7)}" fill="none" stroke="var(--err)" stroke-width="1.8" opacity="0.8"/>`);
    }
  }

  // ── КОРПУС ────────────────────────────────────────────────
  // Не один многоугольник, а НАБОР ПЛИТ: борт, скула, лоб, крыша, корма. У каждой
  // свой градиент — отсюда объём и «сварная» читаемость, как у настоящей брони.
  const noseTop = D.kind === 'wheel' ? L - 3.0 : D.kind === 'spg' ? L * 0.66 : L - 3.3;
  const beltY = floor + (top - floor) * 0.46;              // линия стыка борта и скулы
  const side = [[0.16, floor], [noseTop, floor], [noseTop + 0.9, floor + 0.1], [noseTop + 0.55, beltY], [0.16, beltY]];
  P.push(plate(side, -0.06, 2.6));                          // нижний борт (в тени)
  const upper = [[0.16, beltY], [noseTop + 0.55, beltY], [L - 0.35, top - 0.5], [L - 3.0 > 0.5 ? noseTop : 0.6, top], [0.16, top]];
  P.push(plate(upper, 0.10, 2.4));                          // верхний борт / надгусеничная полка
  // Лобовая плита — отдельной гранью, светлее всех: она смотрит вверх-вперёд.
  P.push(plate([[noseTop, top], [L - 0.3, floor + 0.62], [L - 0.12, floor + 0.4], [noseTop - 0.35, top - 0.02]], 0.24, 2.2));
  // Крыша — узкая светлая полоса поверху.
  P.push(plate([[0.16, top], [noseTop, top], [noseTop - 0.1, top - 0.13], [0.24, top - 0.13]], 0.34, 1.6));
  // Кормовой лист со скосом.
  P.push(plate([[0.16, floor + 0.05], [0.16, top], [-0.12, top - 0.25], [-0.1, floor + 0.2]], -0.16, 2));

  // Сварные швы вдоль борта + ряд болтов по надгусеничной полке.
  P.push(seam(0.2, beltY, noseTop + 0.5, beltY, 0.6));
  for (let x = 0.5; x < noseTop; x += 0.42) P.push(bolt(x, beltY + 0.07));
  // Вертикальные шпангоуты — плотность постоянная в метрах.
  for (let x = 0.9; x < noseTop; x += 1.15) P.push(seam(x, floor + 0.06, x, top - 0.04, 0.35));

  // Навесная динамическая защита: отдельные бруски, чем плотнее броня — тем больше.
  const bricks = Math.round(3 + aRt * 9);
  if (aRt > 0.12) for (let i = 0; i < bricks; i++) {
    const w = (noseTop - 0.7) / bricks, x = 0.45 + w * i;
    P.push(box(x + 0.03, beltY + 0.12, w - 0.09, Math.min(0.42, (top - beltY) * 0.55), 0.16));
  }
  // Противокумулятивный экран поверх гусеницы — только у тяжёлых.
  if (track && aRt > 0.45) {
    const n = Math.max(3, Math.round((noseTop - 0.6) / 0.85));
    for (let i = 0; i < n; i++) {
      const w = (noseTop - 0.6) / n, x = 0.45 + w * i;
      P.push(plate([[x, floor - 0.02], [x + w - 0.05, floor - 0.02], [x + w - 0.05, floor - 0.5], [x, floor - 0.5]], -0.1, 1.8));
    }
  }

  // ── ОБВЕС: то, чем машина отличается от бруска ─────────────
  // Фары, буксирные крюки, ящик ЗИП, выхлоп, канистры — мелочь, которую глаз
  // читает как «вещь, которой пользуются».
  P.push(box(L - 1.05, top - 0.42, 0.26, 0.2, 0.3));                       // блок фары
  P.push(`<rect x="${afN(X(L - 1.0))}" y="${afN(Y(top - 0.26))}" width="${afN(px(0.16))}" height="${afN(px(0.12))}" fill="var(--te)" opacity="0.6"/>`);
  P.push(box(0.62, floor + 0.12, 0.8, 0.34, 0.02));                        // ящик ЗИП на борту
  for (let i = 0; i < 2; i++) P.push(box(1.6 + i * 0.42, floor + 0.14, 0.34, 0.4, -0.02));   // канистры
  P.push(`<path d="${M(-0.05, floor + 0.5) + Ln(-0.28, floor + 0.5)}" fill="none" stroke="${afSh(tint, -0.2)}" stroke-width="${afN(px(0.08))}" stroke-linecap="round"/>`);   // буксирный крюк
  if (track) P.push(box(0.3, top - 0.06, 0.5, 0.16, 0.1));                 // выхлопной коллектор
  if (D.kind === 'wheel') {                                                // аппарель и десантный люк
    P.push(seam(0.2, floor + 0.1, 0.2, top - 0.1, 0.7));
    P.push(box(0.24, floor + 0.3, 0.06, 0.9, 0.2));
  }
  // Люки экипажа на крыше — по одному на человека.
  const hatches = Math.min(4, C.crew || 1);
  for (let i = 0; i < hatches; i++) {
    const x = Math.min(noseTop - 0.7, L * 0.24 + i * 0.72);
    P.push(afSolid(poly([[x, top], [x + 0.5, top], [x + 0.46, top + 0.07], [x + 0.04, top + 0.07]]), afSh(tint, 0.16), 1.4, tint));
  }

  // ── БАШНЯ И СТВОЛЫ ────────────────────────────────────────
  const ws = (C.weapons || []).slice().sort((a, b) => (b.capacityPenalty || 0) - (a.capacityPenalty || 0));
  const main = ws[0] || null, aux = ws.slice(1, 4);
  // Ствол: труба + теплозащитный кожух + эжектор + дульный тормоз.
  const barrel = (bx, by, bl, cal, brake) => {
    const S = [];
    S.push(afSolid(poly([[bx, by - cal], [bx + bl, by - cal * 0.82], [bx + bl, by + cal * 0.82], [bx, by + cal]]), afGrad(tint, Y(by + cal), Y(by - cal), 0.12), 1.8, tint));
    S.push(box(bx + bl * 0.34, by - cal * 1.5, bl * 0.22, cal * 3, 0.2));                 // эжектор
    for (let i = 1; i < 5; i++) S.push(seam(bx + bl * i / 5, by - cal, bx + bl * i / 5, by + cal, 0.3));
    if (brake) {
      S.push(box(bx + bl - 0.42, by - cal * 1.9, 0.42, cal * 3.8, 0.24));
      S.push(seam(bx + bl - 0.28, by - cal * 1.9, bx + bl - 0.28, by + cal * 1.9, 0.5));
      S.push(seam(bx + bl - 0.14, by - cal * 1.9, bx + bl - 0.14, by + cal * 1.9, 0.5));
    }
    return S.join('');
  };
  if (D.kind === 'spg') {
    const cx0 = L * 0.14, cx1 = L * 0.62, ct = top + 1.05;
    P.push(plate([[cx0, top], [cx0 + 0.3, ct], [cx1 - 0.7, ct], [cx1, top + 0.4], [cx1, top]], 0.14, 2.6));   // рубка
    P.push(plate([[cx0 + 0.3, ct], [cx1 - 0.7, ct], [cx1 - 0.78, ct - 0.12], [cx0 + 0.36, ct - 0.12]], 0.36, 1.6));
    for (let x = cx0 + 0.55; x < cx1 - 0.85; x += 0.5) P.push(bolt(x, ct - 0.06));
    P.push(box(cx0 + 0.45, top + 0.3, 0.5, 0.4, 0.06));                                   // люк наводчика
    if (main) {
      const cal = Math.min(0.32, 0.095 + (main.capacityPenalty || 4) * 0.011);
      const bl = Math.min(7.5, 3.2 + (main.capacityPenalty || 4) * 0.3);
      const by = top + 0.6;
      P.push(plate([[cx1 - 0.55, by - cal * 2.4], [cx1 + 0.35, by - cal * 1.6], [cx1 + 0.35, by + cal * 1.6], [cx1 - 0.55, by + cal * 2.4]], 0.06, 2));   // люлька
      P.push(barrel(cx1 + 0.2, by, bl, cal, true));
    }
    // Сошники: САУ упирается в грунт при выстреле.
    P.push(plate([[0.15, floor], [-0.95, 0.06], [-0.5, 0.06], [0.35, floor - 0.22]], -0.2, 2));
  } else {
    const tw = D.kind === 'wheel' ? 1.9 : 3.6, th = D.kind === 'wheel' ? 0.6 : 0.95;
    const tx = D.kind === 'wheel' ? L * 0.42 : L * 0.28;
    P.push(box(tx + 0.15, top, tw - 0.3, 0.09, -0.1));                                    // погон башни
    P.push(plate([[tx, top + 0.07], [tx + 0.42, top + th], [tx + tw - 0.85, top + th], [tx + tw, top + th * 0.42], [tx + tw, top + 0.07]], 0.12, 2.8));
    P.push(plate([[tx + 0.42, top + th], [tx + tw - 0.85, top + th], [tx + tw - 0.92, top + th - 0.11], [tx + 0.5, top + th - 0.11]], 0.36, 1.6));  // крыша башни
    for (let x = tx + 0.6; x < tx + tw - 0.9; x += 0.45) P.push(bolt(x, top + th - 0.055));
    // Командирская башенка с прибором наблюдения.
    P.push(box(tx + 0.55, top + th, 0.45, 0.22, 0.22));
    P.push(`<rect x="${afN(X(tx + 0.66))}" y="${afN(Y(top + th + 0.16))}" width="${afN(px(0.14))}" height="${afN(px(0.09))}" fill="var(--te)" opacity="0.7"/>`);
    // Блок дымовых гранатомётов — по три трубы.
    for (let i = 0; i < 3; i++) P.push(box(tx + tw - 1.15 + i * 0.16, top + th * 0.55, 0.12, 0.26, 0.1));
    // Прицел наводчика в лобовой скуле башни.
    P.push(`<rect x="${afN(X(tx + tw - 0.5))}" y="${afN(Y(top + th * 0.86))}" width="${afN(px(0.3))}" height="${afN(px(0.14))}" fill="var(--te)" opacity="0.72" stroke="${AF_INK}" stroke-width="0.6"/>`);
    if (main) {
      const cal = Math.min(0.28, 0.06 + (main.capacityPenalty || 3) * 0.0105);
      const bl = Math.min(6.5, 2.4 + (main.capacityPenalty || 3) * 0.28);
      const by = top + th * 0.5;
      P.push(plate([[tx + tw - 0.55, by - cal * 2.6], [tx + tw + 0.1, by - cal * 1.8], [tx + tw + 0.1, by + cal * 1.8], [tx + tw - 0.55, by + cal * 2.6]], 0.08, 2.2));  // маска
      P.push(barrel(tx + tw, by, bl, cal, cal > 0.15));
    }
    aux.forEach((w, i) => {
      const mx = tx + 0.5 + i * 0.62, my = top + th + (i === 0 ? 0.22 : 0);
      P.push(box(mx, my, 0.1, 0.16, 0.1));
      P.push(afSolid(poly([[mx + 0.04, my + 0.16], [mx + 0.72, my + 0.19], [mx + 0.72, my + 0.13], [mx + 0.04, my + 0.1]]), afSh(tint, -0.22), 1.2, tint));
    });
    // Антенна связи.
    P.push(`<path d="${M(tx + 0.35, top + th) + Ln(tx + 0.05, top + th + 1.2)}" fill="none" stroke="${afSh(tint, -0.25)}" stroke-width="1.3"/>`);
  }

  // Щит — купол поля над машиной.
  if (C.shieldObj && C.shieldObj.shield > 0) {
    P.push(`<path d="${M(-0.5, 0)} Q${p(L / 2, top + 2.7)} ${p(L + 0.5, 0)}" fill="none" stroke="var(--te)" stroke-width="1.6" stroke-dasharray="7 5" opacity="0.55"/>`);
  }
  return P.join('');
}

